package com.fourtwentykc;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("fourtwentykc")
public interface FourTwentyKcConfig extends Config
{
	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat messages",
		description = "Show a message in chat when a tracked count reaches 420"
	)
	default boolean chatMessages()
	{
		return true;
	}
}

package com.fourtwentykc;

import com.google.inject.Provides;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "420 kc",
	description = "Celebrate when boss, activity, or clue counts reach 420",
	tags = {"420", "kc", "boss", "kill count", "activity", "clue", "clue scroll"}
)
public class FourTwentyKcPlugin extends Plugin
{
	// Mirrors RuneLite's ChatCommandsPlugin KILLCOUNT_PATTERN: the game says
	// "kill count" for bosses but "completion count" for the Gauntlet, "completed"
	// for raids, "subdued" for Wintertodt, plus harvest/lap/success variants.
	// Matching only "kill count" missed a 420 Gauntlet completion (2026-07-28).
	// The number keeps its <col> wrapper as the discriminator, so this stays as
	// strict as RuneLite's own parser.
	static final Pattern KC_PATTERN = Pattern.compile(
		"Your (?:completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?.+?(?:</col>)? "
			+ "(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?"
			+ "is: ?<col=[0-9a-f]{6}>([0-9,]+)</col>");

	// The count-bearing messages that do NOT say "count is:" at all, from the
	// same ChatCommandsPlugin catalog (2026-07-30 audit - the full sweep after
	// the Gauntlet taught us Jagex never uses one wording when five will do).
	// One capturing group each: the count.
	static final Pattern SEPULCHRE_PATTERN = Pattern.compile(
		"You have completed Floor \\d of the Hallowed Sepulchre! Total completions: "
			+ "<col=ff0000>([0-9,]+)</col>\\.");
	static final Pattern GRAND_HALLOWED_COFFIN_PATTERN = Pattern.compile(
		"You have opened the Grand Hallowed Coffin <col=ff0000>([0-9,]+)</col> times?!");
	static final Pattern RIFTS_CLOSED_PATTERN = Pattern.compile(
		"Amount of Rifts you have closed: <col=ff0000>([0-9,]+)</col>\\.",
		Pattern.CASE_INSENSITIVE);
	static final Pattern HUNTER_RUMOUR_PATTERN = Pattern.compile(
		"You have completed <col=[0-9a-f]{6}>([0-9,]+)</col> rumours? for the Hunter Guild\\.");
	static final Pattern BIRD_EGG_PATTERN = Pattern.compile(
		"You have made <col=ff0000>([0-9,]+)</col> offerings?\\.");
	static final Pattern CHEST_OPENING_PATTERN = Pattern.compile(
		"You have opened (?:the )?(?:crystal chest|Larran's big chest|Larran's small chest"
			+ "|Brimstone chest) ([0-9,]+) times\\.");

	// RuneLite parses clue totals separately in LootTrackerPlugin. The count has
	// no dedicated col wrapper and precedes the tier; the optional plural matches
	// both first and later completions.
	static final Pattern TREASURE_TRAIL_PATTERN = Pattern.compile(
		"You have completed ([0-9,]+) [a-z]+ Treasure Trails?\\.");

	// Duel Arena wins/losses are in RuneLite's catalog but the content left the
	// game; those messages can no longer occur, so they are deliberately absent.
	static final Pattern[] KC_PATTERNS = {
		KC_PATTERN, SEPULCHRE_PATTERN, GRAND_HALLOWED_COFFIN_PATTERN,
		RIFTS_CLOSED_PATTERN, HUNTER_RUMOUR_PATTERN, BIRD_EGG_PATTERN,
		CHEST_OPENING_PATTERN, TREASURE_TRAIL_PATTERN,
	};

	/** The count carried by a game message, or null if it carries none. */
	static String countFrom(String message)
	{
		for (Pattern pattern : KC_PATTERNS)
		{
			Matcher matcher = pattern.matcher(message);
			if (matcher.find())
			{
				return matcher.group(1);
			}
		}
		return null;
	}

	@Inject
	private FourTwentyKcConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Provides
	FourTwentyKcConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FourTwentyKcConfig.class);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		// Match the raw message: the <col> tags around the number are part of
		// the patterns' strictness, so they must survive to the matcher.
		String count = countFrom(event.getMessage());
		if (count == null)
		{
			return;
		}

		String kcStr = count.replace(",", "");
		int kc;
		try
		{
			kc = Integer.parseInt(kcStr);
		}
		catch (NumberFormatException e)
		{
			return;
		}

		if (kc == 420 && config.chatMessages())
		{
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.GAMEMESSAGE)
				.runeLiteFormattedMessage("<col=00ff00>420 kc</col>: blaze it!")
				.build());
		}
	}
}

package com.fourtwentykc;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class FourTwentyKcPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(FourTwentyKcPlugin.class);
		RuneLite.main(args);
	}
}

package com.fourtwentykc;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The pattern must recognize every wording the game uses for a countable
 * completion, not just "kill count" - a 420 Gauntlet completion slipped
 * through the old boss-only pattern (2026-07-28). Message strings here are
 * the game's real formats with the number's col wrapper intact.
 */
public class KcPatternTest
{
	private static String kcOf(String message)
	{
		return FourTwentyKcPlugin.countFrom(message);
	}

	@Test
	public void bossKillCountStillMatches()
	{
		assertEquals("420", kcOf("Your Zulrah kill count is: <col=ff0000>420</col>."));
	}

	@Test
	public void gauntletCompletionCountMatches()
	{
		// The message that started this: 420 Gauntlet, no blaze.
		assertEquals("420", kcOf("Your Gauntlet completion count is: <col=ff0000>420</col>."));
		assertEquals("420", kcOf("Your Corrupted Gauntlet completion count is: <col=ff0000>420</col>."));
	}

	@Test
	public void raidCompletedCountMatches()
	{
		assertEquals("420", kcOf("Your completed Theatre of Blood count is: <col=ff0000>420</col>."));
		assertEquals("420", kcOf("Your completed Chambers of Xeric count is: <col=ff0000>420</col>."));
		assertEquals("420", kcOf("Your completed Tombs of Amascut: Expert Mode count is: <col=ff0000>420</col>."));
	}

	@Test
	public void completionCountForPrefixMatches()
	{
		assertEquals("420", kcOf("Your completion count for Tempoross is: <col=ff0000>420</col>."));
	}

	@Test
	public void subduedWintertodtMatches()
	{
		assertEquals("420", kcOf("Your subdued Wintertodt count is: <col=ff0000>420</col>."));
	}

	@Test
	public void harvestAndLapCountsMatch()
	{
		assertEquals("420", kcOf("Your Herbiboar harvest count is: <col=ff0000>420</col>."));
		assertEquals("420", kcOf("Your Prifddinas Agility Course lap count is: <col=ff0000>420</col>."));
	}

	@Test
	public void commasSurviveExtraction()
	{
		assertEquals("1,420", kcOf("Your Barrows Chests kill count is: <col=ff0000>1,420</col>."));
	}

	@Test
	public void nearMissCountsStillMatchThePattern()
	{
		// The 420 gate is the plugin's job, not the pattern's.
		assertEquals("419", kcOf("Your Gauntlet completion count is: <col=ff0000>419</col>."));
	}

	@Test
	public void unwrappedNumbersDoNotMatch()
	{
		// The col wrapper is the discriminator against arbitrary "is: N" text,
		// same as RuneLite's own parser.
		assertFalse(FourTwentyKcPlugin.KC_PATTERN.matcher(
			"Your bank PIN is: 420.").find());
		assertFalse(FourTwentyKcPlugin.KC_PATTERN.matcher(
			"Your kill count is over 420, whatever that means.").find());
	}

	@Test
	public void colWrappedBossNameAlsoMatches()
	{
		// Some messages color the boss name too.
		assertEquals("420", kcOf(
			"Your <col=ff0000>TzTok-Jad</col> kill count is: <col=ff0000>420</col>."));
	}

	@Test
	public void plainChatDoesNotMatch()
	{
		assertTrue(kcOf("blaze it") == null);
	}

	// The 2026-07-30 full-catalog audit: every count-bearing message shape in
	// RuneLite's ChatCommandsPlugin that does not say "count is:". Formats are
	// their exact regex targets.

	@Test
	public void sepulchreTotalCompletionsMatches()
	{
		assertEquals("420", kcOf(
			"You have completed Floor 5 of the Hallowed Sepulchre! Total completions: <col=ff0000>420</col>."));
	}

	@Test
	public void grandHallowedCoffinMatches()
	{
		assertEquals("420", kcOf(
			"You have opened the Grand Hallowed Coffin <col=ff0000>420</col> times!"));
	}

	@Test
	public void riftsClosedMatches()
	{
		assertEquals("420", kcOf(
			"Amount of Rifts you have closed: <col=ff0000>420</col>."));
	}

	@Test
	public void hunterRumoursMatch()
	{
		assertEquals("420", kcOf(
			"You have completed <col=ff3045>420</col> rumours for the Hunter Guild."));
	}

	@Test
	public void birdEggOfferingsMatch()
	{
		assertEquals("420", kcOf(
			"You have made <col=ff0000>420</col> offerings."));
	}

	@Test
	public void chestOpeningsMatch()
	{
		assertEquals("420", kcOf("You have opened the crystal chest 420 times."));
		assertEquals("420", kcOf("You have opened Larran's big chest 420 times."));
		assertEquals("420", kcOf("You have opened the Brimstone chest 420 times."));
	}

	@Test
	public void chestNeverOpenedDoesNotMatch()
	{
		// The "never opened" and "opened once" variants carry no digits and
		// must stay silent.
		assertTrue(kcOf("You have never opened the crystal chest.") == null);
		assertTrue(kcOf("You have opened the crystal chest once.") == null);
	}

	@Test
	public void collectionLogItemDoesNotMatch()
	{
		// A count-free message from the same catalog: not a KC, never fires.
		assertTrue(kcOf("New item added to your collection log: Twisted bow") == null);
	}

	// Clue totals use LootTrackerPlugin's parser rather than the ChatCommands
	// count catalog. The count precedes the tier and Trail may be singular.

	@Test
	public void clueCompletionsMatch()
	{
		assertEquals("420", kcOf("You have completed 420 master Treasure Trails."));
		assertEquals("420", kcOf("You have completed 420 beginner Treasure Trails."));
		assertEquals("69", kcOf("You have completed 69 elite Treasure Trails."));
	}

	@Test
	public void firstClueCompletionSingularMatches()
	{
		assertEquals("1", kcOf("You have completed 1 hard Treasure Trail."));
	}
}
